/**
 * BigQuery engine: GoogleSQL generated by the LLM runs as BigQuery query jobs through the REST API,
 * so data stays in BigQuery. Every statement passes a dry run that only admits SELECT, and every
 * job is bounded by maximumBytesBilled and queryTimeoutMs.
 */
import { randomUUID } from 'crypto';

import { BIGQUERY_INSTRUCTIONS, BigQueryQueryDialect } from '../../query/bigquery';
import { utf8ByteLength } from '../../util/bytes';
import { DEFAULT_METRICS, parseProfileOptions } from '../../util/profile';
import { executionResult, maxResultBytes, maxRows } from '../../util/result';

import { BigQueryApi, BigQueryError, DEFAULT_API_ENDPOINT } from './api';
import { googleAuth } from './auth';
import { profileTables } from './profile';
import { getBigQuerySchema } from './schema';
import { fieldType, rowObject } from './values';

import type { DatasetReference, JobReference, QueryRequest, QueryResults } from './api';
import type {
  AnalysisEngine,
  BigQuerySourceOptions,
  DataModel,
  DataSourceConfig,
  ExecutionOptions,
  ExecutionResult,
  LLMConfig,
  Profile,
  ProfileOptions,
  QueryColumn,
  Schema,
  TranslationResult,
} from '../../types';

const DEFAULT_MAXIMUM_BYTES_BILLED = 1024 ** 3;
const DEFAULT_QUERY_TIMEOUT_MS = 30_000;
/** Server-side wait per jobs.query or getQueryResults call, matching the API default of 10 seconds. */
const POLL_WAIT_MS = 10_000;

interface Connection {
  api: BigQueryApi;
  /** Project that runs and pays for query jobs. */
  projectId: string;
  /** Dataset exposed to the model and used to resolve unqualified table names. */
  dataset: DatasetReference;
  location?: string;
  tables?: string[];
  maximumBytesBilled: number;
  queryTimeoutMs: number;
}

interface Rows {
  columns: QueryColumn[];
  rows: Record<string, unknown>[];
  truncatedBy?: 'maxResultBytes';
}

function positiveInteger(value: unknown, name: string, fallback: number): number {
  if (value === undefined) return fallback;
  if (!Number.isSafeInteger(value) || (value as number) <= 0) {
    throw new Error(`BigQuery ${name} must be a positive integer`);
  }
  return value as number;
}

/** Accept `dataset` or `project.dataset`; project IDs may contain dots (`example.com:project`), dataset IDs cannot. */
function parseDataset(dataset: unknown): { projectId?: string; datasetId: string } {
  if (typeof dataset !== 'string') throw new Error('BigQuery sources require a dataset');
  const split = dataset.lastIndexOf('.');
  const datasetId = dataset.slice(split + 1);
  const projectId = split === -1 ? undefined : dataset.slice(0, split);
  if (!/^[A-Za-z0-9_]{1,1024}$/.test(datasetId) || projectId === '') {
    throw new Error(`Invalid BigQuery dataset "${dataset}"; use "dataset" or "project.dataset"`);
  }
  return { projectId, datasetId };
}

function apiEndpoint(endpoint: unknown): string {
  if (endpoint === undefined) return DEFAULT_API_ENDPOINT;
  if (typeof endpoint !== 'string' || !/^https?:\/\/[^/]/i.test(endpoint)) {
    throw new Error('BigQuery apiEndpoint must be an http(s) URL');
  }
  return endpoint;
}

function datasetName({ projectId, datasetId }: DatasetReference): string {
  return `${projectId}.${datasetId}`;
}

function withHint(error: BigQueryError, hint: string): BigQueryError {
  const separator = /[.!?]$/.test(error.message) ? ' ' : '. ';
  return new BigQueryError(`${error.message}${separator}${hint}`, error);
}

/** Add AVA-specific guidance to errors whose fix is an AVA option or an IAM grant. */
function explain(
  error: unknown,
  connection: Pick<Connection, 'projectId' | 'dataset' | 'maximumBytesBilled'>
): unknown {
  if (!(error instanceof BigQueryError)) return error;
  if (error.reason === 'bytesBilledLimitExceeded') {
    return withHint(
      error,
      `The source allows ${connection.maximumBytesBilled} bytes billed per query (maximumBytesBilled); read fewer columns or partitions, or raise the limit.`
    );
  }
  if (error.reason === 'accessDenied' || error.status === 401) {
    return withHint(
      error,
      `The credentials need roles/bigquery.jobUser on project ${
        connection.projectId
      } and roles/bigquery.dataViewer on dataset ${datasetName(connection.dataset)}.`
    );
  }
  if (error.reason === 'responseTooLarge') {
    return withHint(error, 'Aggregate or filter the query so its result fits in a response.');
  }
  return error;
}

function queryRequest(connection: Connection, sql: string): QueryRequest {
  return {
    query: sql,
    useLegacySql: false,
    defaultDataset: connection.dataset,
    ...(connection.location ? { location: connection.location } : {}),
  };
}

async function connect(options: BigQuerySourceOptions): Promise<Connection> {
  const dataset = parseDataset(options.dataset);
  const tables = options.tables;
  if (
    tables !== undefined &&
    (!Array.isArray(tables) ||
      !tables.length ||
      tables.some((table) => typeof table !== 'string' || !table) ||
      new Set(tables).size !== tables.length)
  ) {
    throw new Error('BigQuery tables must be a non-empty list of unique table names');
  }
  const maximumBytesBilled = positiveInteger(
    options.maximumBytesBilled,
    'maximumBytesBilled',
    DEFAULT_MAXIMUM_BYTES_BILLED
  );
  const queryTimeoutMs = positiveInteger(options.queryTimeoutMs, 'queryTimeoutMs', DEFAULT_QUERY_TIMEOUT_MS);
  const endpoint = apiEndpoint(options.apiEndpoint);

  const auth = await googleAuth(options);
  const projectId =
    options.projectId || process.env.GOOGLE_CLOUD_PROJECT || process.env.GCLOUD_PROJECT || auth.projectId;
  if (!projectId) {
    throw new Error('BigQuery sources require projectId when the credentials and environment do not name a project');
  }

  const connection: Connection = {
    api: new BigQueryApi({ endpoint, token: auth.token }),
    projectId,
    dataset: { projectId: dataset.projectId ?? projectId, datasetId: dataset.datasetId },
    tables,
    maximumBytesBilled,
    queryTimeoutMs,
  };
  try {
    // Fail at load time when the dataset is invisible or jobs cannot run in the project.
    const { location } = await connection.api.getDataset(connection.dataset);
    connection.location = location || undefined;
    await connection.api.query(connection.projectId, { ...queryRequest(connection, 'SELECT 1'), dryRun: true });
  } catch (error) {
    if (error instanceof BigQueryError && error.status === 404) {
      throw withHint(
        error,
        `Check that dataset ${datasetName(connection.dataset)} exists and that projectId ${
          connection.projectId
        } is correct.`
      );
    }
    throw explain(error, connection);
  }
  return connection;
}

export class BigQueryEngine implements AnalysisEngine {
  readonly language = {
    name: 'BigQuery GoogleSQL dialect',
    fence: 'sql',
    instructions: BIGQUERY_INSTRUCTIONS,
  };

  private connection: Connection | null = null;
  /** Aborted by dispose() to stop polling and cancel running jobs. */
  private controller = new AbortController();
  private readonly queryDialect: BigQueryQueryDialect;

  constructor(llmConfig: LLMConfig) {
    this.queryDialect = new BigQueryQueryDialect(llmConfig);
  }

  async load(config: DataSourceConfig): Promise<void> {
    await this.dispose();
    if (config.type !== 'bigquery') {
      throw new Error(`BigQueryEngine only supports 'bigquery' data sources, got '${config.type}'`);
    }
    this.controller = new AbortController();
    this.connection = await connect(config.options);
  }

  async schema(): Promise<Schema> {
    const connection = this.loaded();
    return getBigQuerySchema(connection.api, connection.dataset, connection.tables);
  }

  async profile(schema: Schema, options: ProfileOptions = {}): Promise<Profile> {
    this.loaded();
    return profileTables(
      async (sql) => (await this.run(sql)).rows,
      schema,
      parseProfileOptions(options, { metrics: DEFAULT_METRICS })
    );
  }

  async getDSL(query: string, dataModel: DataModel): Promise<TranslationResult> {
    this.loaded();
    return this.queryDialect.getDSL(query, dataModel);
  }

  async execute<T = Record<string, unknown>>(dsl: string, options?: ExecutionOptions): Promise<ExecutionResult<T>> {
    const connection = this.loaded();
    const sql = await this.queryDialect.validateDSL(dsl, async (statement) => {
      const { statementType } = await connection.api
        .query(
          connection.projectId,
          { ...queryRequest(connection, statement), dryRun: true },
          { signal: this.controller.signal }
        )
        .catch((error: unknown) => Promise.reject(explain(error, connection)));
      return { statementType };
    });
    const { rows, columns, truncatedBy } = await this.run(sql, options);
    return executionResult(rows as T[], columns, options, truncatedBy);
  }

  async dispose(): Promise<void> {
    this.connection = null;
    this.controller.abort(new BigQueryError('BigQuery engine was disposed'));
  }

  private loaded(): Connection {
    if (!this.connection) throw new Error('No data loaded. Please call source() first.');
    return this.connection;
  }

  /**
   * Run a query job and read the first maxRows + 1 rows in result order, without rewriting the SQL.
   * The job is cancelled when it outlives queryTimeoutMs or the engine is disposed.
   */
  private async run(sql: string, options: ExecutionOptions = {}): Promise<Rows> {
    const connection = this.loaded();
    const { api } = connection;
    const signal = this.controller.signal;
    const limit = maxRows(options) + 1;
    const byteLimit = maxResultBytes(options);
    const deadline = Date.now() + connection.queryTimeoutMs;
    const wait = () => Math.max(Math.min(POLL_WAIT_MS, deadline - Date.now()), 0);
    const timeout = () =>
      new BigQueryError(`BigQuery query exceeded queryTimeoutMs (${connection.queryTimeoutMs} ms)`, {
        reason: 'timeout',
      });

    let job: JobReference | undefined;
    let complete = false;
    try {
      let page: QueryResults = await api.query(
        connection.projectId,
        {
          ...queryRequest(connection, sql),
          maximumBytesBilled: String(connection.maximumBytesBilled),
          jobTimeoutMs: String(connection.queryTimeoutMs),
          timeoutMs: wait(),
          maxResults: limit,
          // Retrying with the same requestId cannot start a second job.
          requestId: randomUUID(),
          formatOptions: { useInt64Timestamp: true },
        },
        { deadline, signal }
      );
      job = page.jobReference;
      while (!page.jobComplete) {
        if (!job) throw new BigQueryError('BigQuery returned an incomplete query without a job reference');
        if (Date.now() >= deadline) throw timeout();
        page = await api.getQueryResults(job, { maxResults: limit, timeoutMs: wait() }, { deadline, signal });
      }
      complete = true;

      const fields = page.schema?.fields ?? [];
      const rows = (page.rows ?? []).map((row) => rowObject(fields, row));
      let bytes = rows.reduce((total, row) => total + utf8ByteLength(JSON.stringify(row)), 0);
      let pageToken = page.pageToken;
      // A page can stop short of maxResults at BigQuery's response size limit.
      while (pageToken && job && rows.length < limit && bytes <= byteLimit) {
        if (Date.now() >= deadline) throw timeout();
        page = await api.getQueryResults(job, { maxResults: limit - rows.length, pageToken }, { deadline, signal });
        for (const row of page.rows ?? []) {
          const record = rowObject(fields, row);
          rows.push(record);
          bytes += utf8ByteLength(JSON.stringify(record));
        }
        pageToken = page.pageToken;
      }

      return {
        columns: fields.map((field) => ({ name: field.name, type: fieldType(field) })),
        rows,
        // Unread pages remain only when the byte budget stopped the reads before the row limit.
        ...(pageToken && rows.length < limit ? { truncatedBy: 'maxResultBytes' as const } : {}),
      };
    } catch (error) {
      if (job && !complete) await api.cancel(job).catch(() => undefined);
      throw explain(signal.aborted ? signal.reason : error, connection);
    }
  }
}
